/**
 * Convert book name to IQ Bible numeric book ID (1-66)
 * @param book - Book name in normalized format (e.g., "genesis", "firstSamuel")
 * @returns Numeric book ID (1-66) or null if not found
 */
export const bookNameToIqBibleBookId = (book: string): number | null => {
  if (!book) {
    return null;
  }

  // Normalize book name: lowercase, remove spaces
  const normalizedBook = book.toLowerCase().trim().replace(/\s+/g, '');

  return BOOK_ID_MAP[normalizedBook] || null;
};

/**
 * Convert verse reference to IQ Bible verseId format (BBCCCVVV)
 * Format: BB (2-digit book ID) + CCC (3-digit chapter) + VVV (3-digit verse)
 * @param book - Book name in normalized format
 * @param chapter - Chapter number
 * @param verse - Verse number
 * @returns 8-digit verseId string (e.g., "01001001" for Genesis 1:1) or null if conversion fails
 */
export const convertToIqBibleVerseId = (
  book: string,
  chapter: number,
  verse: number
): string | null => {
  const bookId = bookNameToIqBibleBookId(book);
  
  if (bookId === null || !chapter || !verse) {
    return null;
  }

  // Pad book ID to 2 digits, chapter to 3 digits, verse to 3 digits
  const bookIdStr = String(bookId).padStart(2, '0');
  const chapterStr = String(chapter).padStart(3, '0');
  const verseStr = String(verse).padStart(3, '0');

  return `${bookIdStr}${chapterStr}${verseStr}`;
};